# Square roots by Newton's method, with holds in holds.debug: claims the
# debug build checks while the program runs, and a release build skips.
def newton_sqrt(a, tol) {
    step guess {
        x = a
    }
    while abs(x * x - a) > tol {
        step update {
            x = (x + a / x) / 2.0
        }
    }
    return x
}

