kernel def block_sum(x: Arr, out: Arr) {
    s = shared(8)
    t = thread_id()
    s[t] = x[block_id() * block_size() + t]
    stride: Int = block_size() // 2
    while stride > 0 {
        barrier()
        if t < stride {
            s[t] = s[t] + s[t + stride]
        }
        stride = stride // 2
    }
    if t == 0 {
        out[block_id()] = s[0]
    }
}

